WITH flattened AS (SELECT id, latency_ms, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, value) SELECT CASE WHEN latency_ms >= 1936 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, COUNT(DISTINCT id) AS distinct_ids, SUM(latency_ms) FILTER (WHERE attr_key = 'trace') AS trace_total_latency_ms, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN attr_key = 'version' THEN 1 END), 0), 2) AS latency_ms_per_version, SORT_ARRAY(COLLECT_SET(attr_key)) AS attr_key_list FROM flattened GROUP BY CASE WHEN latency_ms >= 1936 THEN 'HIGH' ELSE 'LOW' END ORDER BY latency_ms_per_version DESC NULLS LAST;
